// Edit this list: one entry per service you want to watch.
// expectedStatus is optional (default 200).
const targets = [
  { name: 'Main API', url: 'https://api.example.com/health', expectedStatus: 200 },
  { name: 'Website', url: 'https://www.example.com', expectedStatus: 200 },
];

return targets.map((t) => ({ json: { expectedStatus: 200, ...t } }));

const settings = $('Settings').first().json;
const threshold = Math.max(1, Number(settings.failuresBeforeAlert) || 2);
const repeatEvery = Math.max(1, Number(settings.repeatAlertEvery) || 12);
const channel = settings.slackChannel || 'engineering-alerts';

// Remembers failures between runs (kept while the workflow is active).
const memory = $getWorkflowStaticData('global');
memory.failures = memory.failures || {};

const targets = $('Define Targets').all();
const out = [];

$input.all().forEach((res, i) => {
  const idx = res.pairedItem && res.pairedItem.item !== undefined ? res.pairedItem.item : i;
  const target = (targets[idx] || targets[i]).json;
  const r = res.json || {};

  const status = r.statusCode !== undefined ? Number(r.statusCode) : null;
  const expected = Number(target.expectedStatus) || 200;
  const down = status === null || status !== expected;
  const reason = status === null
    ? (r.error && (r.error.message || String(r.error))) || 'No response (timeout or connection error)'
    : `HTTP ${status} (expected ${expected})`;

  const key = target.url;
  const before = memory.failures[key] || 0;
  let text = null;

  if (down) {
    const failures = before + 1;
    memory.failures[key] = failures;
    if (failures === threshold) {
      text = `🚨 *Server health alert*\n*Service:* ${target.name}\n*URL:* ${target.url}\n*Problem:* ${reason}`;
    } else if (failures > threshold && (failures - threshold) % repeatEvery === 0) {
      text = `🚨 *Still down* (${failures} checks in a row)\n*Service:* ${target.name}\n*URL:* ${target.url}\n*Problem:* ${reason}`;
    }
  } else {
    memory.failures[key] = 0;
    if (before >= threshold) {
      text = `✅ *Recovered*\n*Service:* ${target.name}\n*URL:* ${target.url}\nIt was failing for ${before} checks.`;
    }
  }

  if (text) out.push({ json: { channel, text: `${text}\n_${new Date().toUTCString()}_` } });
});

return out;
